INSERT INTO public.learning_questions(question_id,unit_code,mission,difficulty,prompt,choices,answer_index,explanation,page_ref)
SELECT q.question_id,q.unit_code,q.mission,q.difficulty,q.prompt,q.choices,q.answer_index,q.explanation,q.page_ref FROM jsonb_to_recordset($sirahfinal$[{"question_id":"S4P2F01","unit_code":"sirah_t4_p2","mission":6,"difficulty":"Faham","prompt":"رسول اولوا العزم يڠ منريم كتاب انجيل اياله؟","choices":["نبي نوح","نبي ابراهيم","نبي عيسى","نبي موسى"],"answer_index":2,"explanation":"Nabi Isa menerima kitab Injil. Bandingkan kisah Nabi Isa pada m/s 62–64.","page_ref":"62–64"},{"question_id":"S4P2F02","unit_code":"sirah_t4_p2","mission":1,"difficulty":"Faham","prompt":"انتارا يڠ بريكوت سياڤاكه بوكن رسول اولوا العزم؟","choices":["نبي نوح","نبي هارون","نبي موسى","نبي عيسى"],"answer_index":1,"explanation":"Rasul Ulul Azmi ialah Nuh, Ibrahim, Musa, Isa dan Muhammad ﷺ.","page_ref":"29"},{"question_id":"S4P2F03","unit_code":"sirah_t4_p2","mission":5,"difficulty":"Faham","prompt":"ڤادانن ماناكه بتول انتارا رسول دان ڤريستيوا؟","choices":["نبي موسى — ممبله لاوت","نبي نوح — اڤي سجوک","نبي عيسى — ممبينا بهاݢترا","نبي ابراهيم — لاوت تربله"],"answer_index":0,"explanation":"Nabi Musa dikurniakan mukjizat laut terbelah.","page_ref":"55–56"},{"question_id":"S4P2F04","unit_code":"sirah_t4_p2","mission":2,"difficulty":"Faham","prompt":"اڤاكه ڤڠاجرن درڤد نبي نوح مڽامڤايكن دعوه والاوڤون دتنتڠ؟","choices":["مڽره ديري","مڠهينا اورڠ","صابار دان استمرار","مڽمبه برهالا"],"answer_index":2,"explanation":"Kesabaran dan keteguhan Nabi Nuh merupakan contoh Rasul Ulul Azmi.","page_ref":"29–34"},{"question_id":"S4P2F05","unit_code":"sirah_t4_p2","mission":4,"difficulty":"Cabaran","prompt":"سياڤاكه يڠ براوسها منچاري اير انتارا صفا دان مروة؟","choices":["مريم","هاجر","اسيه","خديجة"],"answer_index":1,"explanation":"Hajar berulang-alik mencari air ketika bersama Nabi Ismail.","page_ref":"43–45"},{"question_id":"S4P2F06","unit_code":"sirah_t4_p2","mission":3,"difficulty":"Cabaran","prompt":"دالم كسه نبي ابراهيم اڤي منجادي ...","choices":["سجوک دان سلامت","لبـيه ڤانس","بنجير","ڬونوڠ"],"answer_index":0,"explanation":"Allah menjadikan api sejuk dan selamat bagi Nabi Ibrahim.","page_ref":"41–42"},{"question_id":"S4P2F07","unit_code":"sirah_t4_p2","mission":2,"difficulty":"Cabaran","prompt":"نبي نوح ممبينا بهاݢترا كران اڤا؟","choices":["اونتوق برنياݢ","اونتوق برلاڽر سهاج","اونتوق برساديا مڠهادڤي بنجير","اونتوق برلاوان فرعون"],"answer_index":2,"explanation":"Allah memerintahkan Nabi Nuh membina bahtera sebelum banjir besar.","page_ref":"32–34"},{"question_id":"S4P2F08","unit_code":"sirah_t4_p2","mission":5,"difficulty":"Cabaran","prompt":"انتارا يڠ بريكوت ماناكه ڤادانن يڠ ساله؟","choices":["نبي عيسى — انجيل","نبي موسى — فرعون","نبي نوح — بهاݢترا","نبي ابراهيم — سوڠاي نيل"],"answer_index":3,"explanation":"Sungai Nil dikaitkan dengan kisah Nabi Musa, bukannya Nabi Ibrahim.","page_ref":"43–49"},{"question_id":"S4P2F09","unit_code":"sirah_t4_p2","mission":4,"difficulty":"Cabaran","prompt":"سيكڤ هاجر دالم كسوسهن منونجوقكن ...","choices":["تامع","توكل دان اوسها","كسومبوڠن","سيفت ڤمالس"],"answer_index":1,"explanation":"Hajar berusaha mencari air sambil bertawakal kepada Allah.","page_ref":"44–45"},{"question_id":"S4P2F10","unit_code":"sirah_t4_p2","mission":5,"difficulty":"Cabaran","prompt":"فرعون مننتڠ دعوه نبي سياڤا؟","choices":["نبي موسى","نبي نوح","نبي عيسى","نبي محمد"],"answer_index":0,"explanation":"Nabi Musa diutus menghadap Firaun dan berdakwah kepadanya.","page_ref":"52–55"},{"question_id":"S4P2F11","unit_code":"sirah_t4_p2","mission":3,"difficulty":"Cabaran","prompt":"اڤاكه يڠ دسمبه اوليه قوم نبي ابراهيم سبلم دعوه توحيد؟","choices":["الله يڠ اسا","برهالا","ملايكت","ر سول"],"answer_index":1,"explanation":"Kaum Nabi Ibrahim menyembah berhala, dan baginda menyeru kepada tauhid.","page_ref":"35–40"},{"question_id":"S4P2F12","unit_code":"sirah_t4_p2","mission":6,"difficulty":"Cabaran","prompt":"دالم كسه مريم، معجزه نبي عيسى كتيك بايي اياله؟","choices":["ممبينا بهاݢترا","ممبله لاوت","برچاكڤ","ممچاهكن برهالا"],"answer_index":2,"explanation":"Nabi Isa berkata-kata semasa bayi dengan izin Allah.","page_ref":"59–62"},{"question_id":"S4P2F13","unit_code":"sirah_t4_p2","mission":1,"difficulty":"Cabaran","prompt":"ڤڠاجرن برسما درڤد كساه رسول اولوا العزم اياله ...","choices":["جڠن چوبا لاݢي","اوتاماكن هرتا","جاوهي توحيد","تڬوه برايمن دان صابر"],"answer_index":3,"explanation":"Kisah para Rasul Ulul Azmi menekankan sabar serta teguh beriman.","page_ref":"29–69"},{"question_id":"S4P2F14","unit_code":"sirah_t4_p2","mission":6,"difficulty":"Cabaran","prompt":"دڠن ايزين سياڤاكه معجزه رسول برلاكو؟","choices":["الله","ڤڠيكوت","فرعون","قوم"],"answer_index":0,"explanation":"Mukjizat berlaku dengan izin Allah, seperti kisah Nabi Isa dan Nabi Musa.","page_ref":"55–65"},{"question_id":"S4P3F01","unit_code":"sirah_t4_p3","mission":1,"difficulty":"Faham","prompt":"سياڤاكه صحابة يڠ ايبوڽ برنام صفية بنت عبد المطلب؟","choices":["ابو عبيدة","الزبير","زيد بن ثابت","بلال"],"answer_index":1,"explanation":"Ibu Zubair ialah Safiyyah binti Abdul Muttalib.","page_ref":"73"},{"question_id":"S4P3F02","unit_code":"sirah_t4_p3","mission":6,"difficulty":"Faham","prompt":"ڤادانن ماناكه بتول بڬي صحابة دان صيفتڽ؟","choices":["الزبير — ڤناكوت","ابو عبيدة — بخيل","ابو عبيدة — امانه","الزبير — تيدق ستيا"],"answer_index":2,"explanation":"Abu Ubaidah terkenal dengan sifat amanah.","page_ref":"77–79"},{"question_id":"S4P3F03","unit_code":"sirah_t4_p3","mission":5,"difficulty":"Faham","prompt":"سياڤاكه دڬلر امين الامة؟","choices":["الزبير","علي","عثمان","ابو عبيدة"],"answer_index":3,"explanation":"Amin al-Ummah merujuk Abu Ubaidah al-Jarrah.","page_ref":"78"},{"question_id":"S4P3F04","unit_code":"sirah_t4_p3","mission":6,"difficulty":"Faham","prompt":"كتيك براڤاكه ابو عبيدة وافت منوروت بوكو تيکس؟","choices":["١٨ هجرة","٣٠ هجرة","٤٠ هجرة","٥٨ هجرة"],"answer_index":0,"explanation":"Buku teks menyatakan tahun wafat Abu Ubaidah ialah 18 Hijrah.","page_ref":"80"},{"question_id":"S4P3F05","unit_code":"sirah_t4_p3","mission":2,"difficulty":"Cabaran","prompt":"صحابة يڠ دبساكن سباڬاي سباهاݢين ڤد ١٠ دجنجيكن شرݢ اياله؟","choices":["فرعون","الزبير","نمرود","هامان"],"answer_index":1,"explanation":"Zubair disebut sebagai sahabat yang dijanjikan syurga.","page_ref":"74"},{"question_id":"S4P3F06","unit_code":"sirah_t4_p3","mission":6,"difficulty":"Cabaran","prompt":"صحابة ماناكه يڠ ڤرنه مميمڤين تنترا اسلام؟","choices":["ابو جهل","ابو لهب","ابو عبيدة","فرعون"],"answer_index":2,"explanation":"Antara sumbangan Abu Ubaidah ialah memimpin tentera Islam.","page_ref":"79"},{"question_id":"S4P3F07","unit_code":"sirah_t4_p3","mission":4,"difficulty":"Cabaran","prompt":"كدووا دوا صحابة يڠ دچريتاكن دالم ڤلاجرن اين دكنل كران ...","choices":["مڽمبه برهالا","منولق اسلام","تامع","برچوڠ اونتوق اسلام"],"answer_index":3,"explanation":"Zubair dan Abu Ubaidah sama-sama berjuang membela Islam.","page_ref":"73–80"},{"question_id":"S4P3F08","unit_code":"sirah_t4_p3","mission":1,"difficulty":"Cabaran","prompt":"الزبير دان ابو عبيدة اداله صحابة رسول الله ﷺ. سياڤاكه ڤيمڤين مريك؟","choices":["نبي محمد ﷺ","نبي موسى","فرعون","نمرود"],"answer_index":0,"explanation":"Kedua-duanya ialah sahabat Nabi Muhammad ﷺ.","page_ref":"73–78"},{"question_id":"S4P3F09","unit_code":"sirah_t4_p3","mission":6,"difficulty":"Cabaran","prompt":"دالم كهيدوڤن سِهارين، تيندقن ماناكه منچونتوهي ابو عبيدة؟","choices":["منچيوري","ممڬڠ امانه","منيفو","مڠومڤت"],"answer_index":1,"explanation":"Menjaga amanah meneladani Abu Ubaidah.","page_ref":"78–79"},{"question_id":"S4P3F10","unit_code":"sirah_t4_p3","mission":3,"difficulty":"Cabaran","prompt":"دالم كهيدوڤن سِهارين، تيندقن ماناكه منچونتوهي الزبير؟","choices":["مالس برسوكن","مڽيمڤن دندم","براني ممڤرتاهنكن كبنرن","مڠهينا اورڠ"],"answer_index":2,"explanation":"Kita boleh mencontohi keberanian Zubair mempertahankan kebenaran.","page_ref":"75–76"},{"question_id":"S4P3F11","unit_code":"sirah_t4_p3","mission":1,"difficulty":"Cabaran","prompt":"سياڤاكه ايبو ساودارا رسول الله ﷺ يڠ منجادي ايبو الزبير؟","choices":["عائشة","هاجر","مريم","صفية"],"answer_index":3,"explanation":"Safiyyah ialah ibu Zubair dan ibu saudara Nabi Muhammad ﷺ.","page_ref":"73"},{"question_id":"S4P3F12","unit_code":"sirah_t4_p3","mission":6,"difficulty":"Cabaran","prompt":"ڤڽاكيت اڤاكه يڠ دكاتكن منجادي سبب كوفاتن ابو عبيدة؟","choices":["طاعون","سمسل","باتوق","دمام عادي"],"answer_index":0,"explanation":"Buku teks menyatakan Abu Ubaidah wafat akibat wabak taun.","page_ref":"80"},{"question_id":"S4P3F13","unit_code":"sirah_t4_p3","mission":5,"difficulty":"Cabaran","prompt":"سياڤاكه يڠ ممڤوڽاءي نام اصل عامر بن عبدالله؟","choices":["الزبير","ابو عبيدة","عثمان","سعد"],"answer_index":1,"explanation":"Amir bin Abdullah ialah nama asal Abu Ubaidah yang dicatat.","page_ref":"77"},{"question_id":"S4P3F14","unit_code":"sirah_t4_p3","mission":4,"difficulty":"Cabaran","prompt":"ڤادانن يڠ بتول اياله الزبير — براني، ابو عبيدة — ...","choices":["بخيل","سونمبوڠ","امانه","تامع"],"answer_index":2,"explanation":"Kedua-dua sahabat ini memperlihatkan teladan berani dan amanah.","page_ref":"75–79"},{"question_id":"S4P4F01","unit_code":"sirah_t4_p4","mission":3,"difficulty":"Faham","prompt":"سياڤاكه وانيتا ڤرتام يڠ مڽوکوڠ اسلام درڤد رسول الله ﷺ؟","choices":["عائشة","مريم","هاجر","خديجة"],"answer_index":3,"explanation":"Khadijah merupakan wanita pertama yang memeluk Islam.","page_ref":"86"},{"question_id":"S4P4F02","unit_code":"sirah_t4_p4","mission":1,"difficulty":"Faham","prompt":"ام المؤمنين اداله ڬلرن اونتوق ...","choices":["ايستري نبي محمد ﷺ","سموا راج","انق لالكي","ڤاليمڤيق تنترا"],"answer_index":0,"explanation":"Ummahatul Mukminin ialah gelaran isteri-isteri Nabi Muhammad ﷺ.","page_ref":"84"},{"question_id":"S4P4F03","unit_code":"sirah_t4_p4","mission":2,"difficulty":"Faham","prompt":"ڬلرن الطاهرة برمعنا ...","choices":["ڤندندم","سوچي","ڤما لس","ڤڽاير"],"answer_index":1,"explanation":"Al-Tahirah ialah gelaran yang merujuk kesucian akhlak Khadijah.","page_ref":"86"},{"question_id":"S4P4F04","unit_code":"sirah_t4_p4","mission":2,"difficulty":"Faham","prompt":"ڤادانن اوسيا ڤركهوينن ماناكه بتول منوروت بوكو تيکس؟","choices":["رسول الله ٤٠، خديجة ٢٥","رسول الله ٣٠، خديجة ٣٠","رسول الله ٢٥، خديجة ٤٠","رسول الله ٦٤، خديجة ٦٦"],"answer_index":2,"explanation":"Buku teks menyatakan Rasulullah ﷺ 25 tahun dan Khadijah 40 tahun ketika berkahwin.","page_ref":"85"},{"question_id":"S4P4F05","unit_code":"sirah_t4_p4","mission":3,"difficulty":"Cabaran","prompt":"كتيك رسول الله ﷺ مڠهادڤي اوجين دعوه، خديجة ...","choices":["منجاوهي بڬيندا","منچچلا بڬيندا","تيدق ڤدولي","ممبري سمڠت"],"answer_index":3,"explanation":"Khadijah sentiasa memberi sokongan dan semangat kepada Rasulullah ﷺ.","page_ref":"87"},{"question_id":"S4P4F06","unit_code":"sirah_t4_p4","mission":6,"difficulty":"Cabaran","prompt":"سياڤاكه صحابيه يڠ مروايتكن ٢٢١٠ حديث؟","choices":["عائشة","خديجة","هاجر","صفية"],"answer_index":0,"explanation":"Buku teks mencatat Aisyah meriwayatkan 2,210 hadis.","page_ref":"90"},{"question_id":"S4P4F07","unit_code":"sirah_t4_p4","mission":4,"difficulty":"Cabaran","prompt":"ڤادانن يڠ بتول اياله عائشة — ...","choices":["ايبو نبي عيسى","انق ابو بكر","ايبو نبي اسماعيل","ايستري فرعون"],"answer_index":1,"explanation":"Aisyah ialah puteri Abu Bakar as-Siddiq.","page_ref":"88"},{"question_id":"S4P4F08","unit_code":"sirah_t4_p4","mission":6,"difficulty":"Cabaran","prompt":"كبيجقسن عائشة منجادي روجوقن دالم ...","choices":["علمو برهالا","مڠراڤوه كايۇ","فقه دان حديث","ڤمبيناءن بهاݢترا"],"answer_index":2,"explanation":"Aisyah menjadi rujukan dalam ilmu fikah dan hadis.","page_ref":"90"},{"question_id":"S4P4F09","unit_code":"sirah_t4_p4","mission":5,"difficulty":"Cabaran","prompt":"اڤاكه سيكڤ يڠ بوليه دچونتوهي درڤد عائشة؟","choices":["تامع","سمبوڠ","مڠومڤت","ڤماعف"],"answer_index":3,"explanation":"Aisyah dikenali sebagai seorang yang pemaaf.","page_ref":"89"},{"question_id":"S4P4F10","unit_code":"sirah_t4_p4","mission":4,"difficulty":"Cabaran","prompt":"سياڤاكه ايبو عائشة؟","choices":["ام رومان","صفية","ام حبيبة","خديجة"],"answer_index":0,"explanation":"Ibu Aisyah ialah Ummu Ruman binti Amir.","page_ref":"88"},{"question_id":"S4P4F11","unit_code":"sirah_t4_p4","mission":1,"difficulty":"Cabaran","prompt":"خديجة دان عائشة سام سام ...","choices":["ڤمرينته مصر","ايستري رسول الله ﷺ","فرعون","ڤڽمبه برهالا"],"answer_index":1,"explanation":"Kedua-duanya ialah isteri Nabi Muhammad ﷺ.","page_ref":"84–88"},{"question_id":"S4P4F12","unit_code":"sirah_t4_p4","mission":5,"difficulty":"Cabaran","prompt":"كـأليبيهن عائشة دالم منيمبا علمو اياله ...","choices":["تيدق سوك بلاجر","چڤت لوڤا","كوات حافظن","تيدق ممباچ"],"answer_index":2,"explanation":"Buku teks menyenaraikan daya ingatan kuat sebagai akhlak terpuji Aisyah.","page_ref":"89"},{"question_id":"S4P4F13","unit_code":"sirah_t4_p4","mission":2,"difficulty":"Cabaran","prompt":"اڤاكه سيكڤ خديجة دالم منديديق انق؟","choices":["ممبياركن سهاج","مڠهينا","سنتياس مماراهي","ڤنوه كاسيه سايڠ"],"answer_index":3,"explanation":"Khadijah mengasuh anak-anak dengan kasih sayang.","page_ref":"86"},{"question_id":"S4P4F14","unit_code":"sirah_t4_p4","mission":6,"difficulty":"Cabaran","prompt":"اڤاكه ڤڠاجرن برسما درڤد كساه خديجة دان عائشة؟","choices":["منچاري علمو دان براخلاق بايق","منچاري ڤوجين","مڽكتي راكن","مالس منولوڠ"],"answer_index":0,"explanation":"Kisah kedua-duanya mengajar kita berakhlak baik, berilmu dan bermanfaat.","page_ref":"86–90"}]$sirahfinal$::jsonb) AS q(question_id text,unit_code text,mission int,difficulty text,prompt text,choices jsonb,answer_index int,explanation text,page_ref text)
ON CONFLICT(question_id) DO UPDATE SET unit_code=EXCLUDED.unit_code,mission=EXCLUDED.mission,difficulty=EXCLUDED.difficulty,prompt=EXCLUDED.prompt,choices=EXCLUDED.choices,answer_index=EXCLUDED.answer_index,explanation=EXCLUDED.explanation,page_ref=EXCLUDED.page_ref;
-- Three fixed 50-question sets, no question repeats across sets. Each paper balances lessons 2, 3, 4.
INSERT INTO public.learning_exam_sets(set_id,title,duration_seconds,published)
VALUES(13,'Sirah Final Exam — Set 1',3600,false),(14,'Sirah Final Exam — Set 2',3600,false),(15,'Sirah Final Exam — Set 3',3600,false)
ON CONFLICT(set_id) DO UPDATE SET title=EXCLUDED.title,duration_seconds=EXCLUDED.duration_seconds,published=false;
WITH ranked AS (
 SELECT question_id,unit_code,row_number() over (partition by unit_code order by md5(question_id||':sirah-2026-v1')) as rn
 FROM public.learning_questions WHERE unit_code IN ('sirah_t4_p2','sirah_t4_p3','sirah_t4_p4')
), allotted AS (
 SELECT question_id,
 CASE WHEN unit_code='sirah_t4_p2' THEN (CASE WHEN rn<=17 THEN 13 WHEN rn<=34 THEN 14 ELSE 15 END)
 WHEN unit_code='sirah_t4_p3' THEN (CASE WHEN rn<=17 THEN 13 WHEN rn<=33 THEN 14 ELSE 15 END)
 ELSE (CASE WHEN rn<=16 THEN 13 WHEN rn<=33 THEN 14 ELSE 15 END) END::smallint as set_id
 FROM ranked
), positioned AS (
 SELECT set_id,question_id,row_number() over (partition by set_id order by md5(question_id||':sirah-position-v1'))::smallint as position
 FROM allotted
)
INSERT INTO public.learning_exam_set_questions(set_id,position,question_id)
SELECT set_id,position,question_id FROM positioned
ON CONFLICT(set_id,position) DO NOTHING;